@import url('https://fonts.googleapis.com/css2?family=VT323&family=Orbitron:wght@400;700;900&family=Share+Tech+Mono&display=swap');

:root {
  --bg: #000011;
  --ink: #00ffcc;
  --mid: #ff00ff;
  --border: #00ffcc44;
  --accent: #ffff00;
  --font: 'Share Tech Mono', 'Courier New', monospace;
  --pad-x: 18px;
  --pad-top: 24px;
}

/* ── SCANLINES ── */
.page::before {
  content: '';
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0,255,204,0.03) 2px,
    rgba(0,255,204,0.03) 4px
  );
  pointer-events: none;
  z-index: 9999;
}

/* ── STARFIELD BG ── */
.page::after {
  content: '';
  position: fixed;
  inset: 0;
  background:
    radial-gradient(ellipse at 20% 50%, rgba(255,0,255,0.08) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 20%, rgba(0,255,204,0.08) 0%, transparent 50%),
    radial-gradient(ellipse at 60% 80%, rgba(0,100,255,0.1) 0%, transparent 50%);
  pointer-events: none;
  z-index: 0;
}

body {
  background: var(--bg);
  overflow-x: hidden;
}

/* ── INTRO PANEL ── */
.intro {
  border: 1px solid var(--border);
  background: linear-gradient(135deg, rgba(0,255,204,0.04) 0%, rgba(255,0,255,0.04) 100%);
  padding: 32px;
  position: relative;
  box-shadow: 0 0 40px rgba(0,255,204,0.1), inset 0 0 60px rgba(255,0,255,0.04);
  margin-bottom: 32px;
}

.intro::before {
  content: '✦ WELCOME TO MY PORTFOLIO v2.0 ✦ LOADING COMPLETE ✦ Y2K COMPLIANT ✦';
  display: block;
  font-family: 'VT323', monospace;
  font-size: 13px;
  color: #ff00ff;
  letter-spacing: 3px;
  border-bottom: 1px solid #ff00ff44;
  padding-bottom: 10px;
  margin-bottom: 20px;
  white-space: nowrap;
  overflow: hidden;
  animation: marquee-text 14s linear infinite;
}

@keyframes marquee-text {
  0% { text-indent: 100%; }
  100% { text-indent: -200%; }
}

.intro::after {
  content: '[ SYS: ONLINE ] [ RAM: ∞ MB ] [ CPU: MAXED ] [ COOLNESS: 100% ]';
  display: block;
  font-family: 'VT323', monospace;
  font-size: 12px;
  color: #00ffcc88;
  letter-spacing: 2px;
  border-top: 1px solid #00ffcc22;
  padding-top: 10px;
  margin-top: 20px;
}

.intro-headline {
  font-family: 'Orbitron', sans-serif;
  font-weight: 900;
  font-size: clamp(28px, 6vw, 72px);
  color: #ffffff;
  text-shadow:
    0 0 10px #00ffcc,
    0 0 30px #00ffcc,
    0 0 60px #00ffcc88,
    2px 2px 0 #ff00ff,
    4px 4px 0 #ff00ff55;
  letter-spacing: 2px;
  line-height: 1.1;
}

.bio-text {
  font-family: 'Share Tech Mono', monospace;
  color: #aaffee;
  font-size: 14px;
  line-height: 1.9;
  border-left: 3px solid #00ffcc;
  padding-left: 16px;
  margin-top: 16px;
}

.contact-line {
  font-family: 'Share Tech Mono', monospace;
  color: var(--mid);
  font-size: 13px;
  margin-top: 12px;
}

.contact-line a,
.contact-trigger {
  color: #ffff00 !important;
  text-decoration: none;
  text-shadow: 0 0 8px #ffff00;
  border: 1px solid #ffff0066;
  padding: 2px 8px;
  transition: all 0.2s;
}

.contact-line a:hover,
.contact-trigger:hover {
  background: #ffff00;
  color: #000 !important;
  text-shadow: none;
  box-shadow: 0 0 20px #ffff00;
}

/* ── SECTION LABEL ── */
.section-label {
  font-family: 'Orbitron', sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 6px;
  color: #ff00ff;
  text-transform: uppercase;
  text-shadow: 0 0 10px #ff00ff;
  border-bottom: 1px solid #ff00ff44;
  padding-bottom: 8px;
  margin-bottom: 24px;
}

.section-label::before {
  content: '◈ ';
  color: #00ffcc;
}

.section-label::after {
  content: ' ◈';
  color: #00ffcc;
}

/* ── WORK GRID ── */
.work-section {
  position: relative;
}

.work-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
}

.work-item {
  border: 1px solid #00ffcc33;
  background: linear-gradient(160deg, rgba(0,255,204,0.03) 0%, rgba(255,0,255,0.03) 100%);
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.work-item::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, #ff00ff, #00ffcc, #ffff00, #ff00ff);
  background-size: 200% 100%;
  animation: shimmer 3s linear infinite;
  opacity: 0;
  transition: opacity 0.3s;
}

.work-item:hover::before {
  opacity: 1;
}

@keyframes shimmer {
  0% { background-position: 0% 0%; }
  100% { background-position: 200% 0%; }
}

.work-item::after {
  content: '▶ VIEW PROJECT';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Orbitron', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 4px;
  color: #ffff00;
  text-shadow: 0 0 20px #ffff00;
  background: rgba(0,0,17,0.85);
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}

.work-item:hover::after {
  opacity: 1;
}

.work-item:hover {
  border-color: #00ffcc;
  box-shadow:
    0 0 20px rgba(0,255,204,0.3),
    0 0 60px rgba(0,255,204,0.1),
    inset 0 0 30px rgba(0,255,204,0.05);
  transform: translateY(-3px);
}

.work-image {
  filter: saturate(1.4) contrast(1.1);
  transition: filter 0.3s;
}

.work-item:hover .work-image {
  filter: saturate(1.8) hue-rotate(15deg) contrast(1.2);
}

.work-item-footer {
  padding: 14px 16px;
  border-top: 1px solid #00ffcc22;
  background: rgba(0,0,17,0.6);
}

.work-title {
  font-family: 'Orbitron', sans-serif;
  font-size: 13px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: 1px;
  text-shadow: 0 0 8px rgba(0,255,204,0.5);
}

.work-desc {
  font-family: 'Share Tech Mono', monospace;
  font-size: 12px;
  color: #88ccbb;
  margin-top: 4px;
  line-height: 1.5;
}

/* ── TAGS ── */
.work-tags {
  margin-top: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tag {
  font-family: 'Share Tech Mono', monospace;
  font-size: 10px;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding: 3px 10px;
  border: 1px solid;
  border-radius: 0;
  background: transparent;
  transition: all 0.2s;
}

.tag:nth-child(3n+1) {
  color: #00ffcc;
  border-color: #00ffcc55;
  text-shadow: 0 0 6px #00ffcc;
}

.tag:nth-child(3n+2) {
  color: #ff00ff;
  border-color: #ff00ff55;
  text-shadow: 0 0 6px #ff00ff;
}

.tag:nth-child(3n+3) {
  color: #ffff00;
  border-color: #ffff0055;
  text-shadow: 0 0 6px #ffff00;
}

.tag:hover {
  background: rgba(0,255,204,0.15);
}

/* ── FOOTER ── */
footer {
  border-top: 1px solid #00ffcc22;
  margin-top: 48px;
  padding-top: 24px;
  background: linear-gradient(0deg, rgba(0,255,204,0.02) 0%, transparent 100%);
  position: relative;
}

footer::before {
  content: '— EOF — THANKS 4 VISITING — BEST VIEWED IN INTERNET EXPLORER 6 —';
  display: block;
  font-family: 'VT323', monospace;
  font-size: 13px;
  color: #ff00ff66;
  letter-spacing: 3px;
  text-align: center;
  margin-bottom: 16px;
}

.footer-nav a {
  font-family: 'Share Tech Mono', monospace;
  font-size: 12px;
  color: #00ffcc88;
  text-decoration: none;
  letter-spacing: 2px;
  transition: all 0.2s;
  padding: 2px 6px;
}

.footer-nav a:hover {
  color: #ffff00;
  text-shadow: 0 0 10px #ffff00;
}

/* ── CASE STUDY ── */
.top-nav {
  font-family: 'Share Tech Mono', monospace;
  border-bottom: 1px solid #00ffcc22;
  background: rgba(0,0,17,0.95);
  backdrop-filter: blur(8px);
}

.back-link {
  font-family: 'Share Tech Mono', monospace;
  color: #00ffcc !important;
  text-decoration: none;
  font-size: 13px;
  letter-spacing: 2px;
  text-shadow: 0 0 8px #00ffcc;
}

.back-link::before {
  content: '◀ ';
}

.cs-title {
  font-family: 'Orbitron', sans-serif;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 0 20px #00ffcc, 2px 2px 0 #ff00ff;
}

.cs-section-label {
  font-family: 'Orbitron', sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 5px;
  color: #ff00ff;
  text-shadow: 0 0 8px #ff00ff;
}

.meta-label {
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  letter-spacing: 3px;
  color: #00ffcc88;
  text-transform: uppercase;
}

.meta-value {
  font-family: 'Share Tech Mono', monospace;
  color: #fff;
  text-shadow: 0 0 6px rgba(0,255,204,0.3);
}

.callout {
  border: 1px solid #ff00ff44;
  background: linear-gradient(135deg, rgba(255,0,255,0.05), rgba(0,255,204,0.05));
  padding: 20px 24px;
  position: relative;
  box-shadow: 0 0 30px rgba(255,0,255,0.1);
}

.callout::before {
  content: '★';
  position: absolute;
  top: -10px;
  left: 20px;
  color: #ffff00;
  font-size: 18px;
  text-shadow: 0 0 10px #ffff00;
  background: var(--bg);
  padding: 0 6px;
}

/* ── POPUP ── */
.popup-card {
  background: #000022;
  border: 1px solid #00ffcc55;
  box-shadow:
    0 0 40px rgba(0,255,204,0.2),
    0 0 80px rgba(255,0,255,0.1);
  border-radius: 0;
  position: relative;
}

.popup-card::before {
  content: '◈ CONTACT TERMINAL v2.0K ◈';
  display: block;
  font-family: 'VT323', monospace;
  font-size: 14px;
  letter-spacing: 4px;
  color: #ff00ff;
  text-align: center;
  padding-bottom: 12px;
  border-bottom: 1px solid #ff00ff33;
  margin-bottom: 16px;
}

.popup-title {
  font-family: 'Orbitron', sans-serif;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 0 15px #00ffcc;
  letter-spacing: 2px;
}

.popup-sub {
  font-family: 'Share Tech Mono', monospace;
  color: #88ccbb;
  font-size: 13px;
}

.popup-form input,
.popup-form textarea {
  font-family: 'Share Tech Mono', monospace;
  background: rgba(0,255,204,0.04);
  border: 1px solid #00ffcc33;
  color: #00ffcc;
  border-radius: 0;
  transition: all 0.2s;
  font-size: 13px;
}

.popup-form input:focus,
.popup-form textarea:focus {
  outline: none;
  border-color: #00ffcc;
  box-shadow: 0 0 15px rgba(0,255,204,0.2);
  background: rgba(0,255,204,0.07);
}

.popup-form input::placeholder,
.popup-form textarea::placeholder {
  color: #00ffcc44;
}

.btn-submit {
  font-family: 'Orbitron', sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 4px;
  background: transparent;
  border: 1px solid #00ffcc;
  color: #00ffcc;
  text-shadow: 0 0 8px #00ffcc;
  box-shadow: 0 0 20px rgba(0,255,204,0.2);
  border-radius: 0;
  transition: all 0.2s;
  text-transform: uppercase;
}

.btn-submit:hover {
  background: #00ffcc;
  color: #000;
  text-shadow: none;
  box-shadow: 0 0 30px rgba(0,255,204,0.6);
}

.btn-close {
  font-family: 'Share Tech Mono', monospace;
  background: transparent;
  border: 1px solid #ff00ff33;
  color: #ff00ff88;
  border-radius: 0;
  font-size: 12px;
  letter-spacing: 2px;
  transition: all 0.2s;
}

.btn-close:hover {
  border-color: #ff00ff;
  color: #ff00ff;
  box-shadow: 0 0 15px rgba(255,0,255,0.3);
}

/* ── BLINKING CURSOR ── */
.intro-headline::after {
  content: '_';
  animation: blink 1s step-end infinite;
  color: #00ffcc;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* ── GLITCH ON HOVER ── */
.work-title:hover {
  animation: glitch 0.4s steps(2, end);
}

@keyframes glitch {
  0%   { text-shadow: 2px 0 #ff00ff, -2px 0 #00ffcc; transform: skewX(0deg); }
  25%  { text-shadow: -3px 0 #ff00ff, 3px 0 #00ffcc; transform: skewX(-3deg); }
  50%  { text-shadow: 3px 0 #ff00ff, -3px 0 #00ffcc; transform: skewX(2deg); }
  75%  { text-shadow: -2px 0 #ffff00, 2px 0 #ff00ff; transform: skewX(-1deg); }
  100% { text-shadow: 0 0 8px rgba(0,255,204,0.5); transform: skewX(0deg); }
}

/* ── SCROLLBAR ── */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: #000011; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #ff00ff, #00ffcc);
  box-shadow: 0 0 6px #00ffcc;
}

@media (max-width: 600px) {
  .work-list { grid-template-columns: 1fr !important; }
  .intro { padding: 24px !important; }
  .top-nav { padding: 12px 18px !important; }
  .cs-header { padding: 48px 18px !important; }
  .cs-section { padding: 0 18px !important; }
}

