(function() {
  const colors = ['#00ffcc', '#ff00ff', '#00aaff', '#ff6600'];
  const trail = [];
  const MAX = 18;
  let mouseX = -100, mouseY = -100;

  for (let i = 0; i < MAX; i++) {
    const el = document.createElement('div');
    el.style.cssText = `
      position: fixed;
      width: 8px;
      height: 8px;
      border-radius: 0;
      pointer-events: none;
      z-index: 99999;
      mix-blend-mode: screen;
      transition: opacity 0.3s;
      transform: rotate(45deg);
    `;
    document.body.appendChild(el);
    trail.push({ el, x: -100, y: -100 });
  }

  const onMove = (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;
  };

  window.addEventListener('mousemove', onMove);

  let rafId;
  function animate() {
    let x = mouseX, y = mouseY;
    for (let i = 0; i < MAX; i++) {
      const t = trail[i];
      t.x += (x - t.x) * 0.35;
      t.y += (y - t.y) * 0.35;
      const size = 8 - (i * 0.35);
      const opacity = 1 - (i / MAX);
      const color = colors[i % colors.length];
      t.el.style.left = (t.x - size / 2) + 'px';
      t.el.style.top = (t.y - size / 2) + 'px';
      t.el.style.width = size + 'px';
      t.el.style.height = size + 'px';
      t.el.style.background = color;
      t.el.style.boxShadow = `0 0 ${6 - i * 0.2}px ${color}`;
      t.el.style.opacity = opacity;
      x = t.x;
      y = t.y;
    }
    rafId = requestAnimationFrame(animate);
  }
  animate();

  const ticker = document.createElement('div');
  ticker.style.cssText = `
    position: fixed;
    top: 0; left: 0; right: 0;
    height: 22px;
    background: linear-gradient(90deg, #000011, #0a0033, #000011);
    border-bottom: 1px solid #ff00ff44;
    overflow: hidden;
    z-index: 10000;
    display: flex;
    align-items: center;
    font-family: 'VT323', monospace;
    font-size: 13px;
    color: #ff00ff;
    letter-spacing: 3px;
    pointer-events: none;
  `;
  const msg = '✦ PORTFOLIO LOADED SUCCESSFULLY ✦ Y2K COMPLIANT ✦ NO BUGS FOUND ✦ DIAL-UP LOADING ✦ SITE OF THE DAY ✦ 100% FLASH-FREE ✦ BEST VIEWED 1024×768 ✦ SIGN MY GUESTBOOK ✦ ';
  const span = document.createElement('span');
  span.textContent = msg + msg;
  span.style.cssText = `
    white-space: nowrap;
    display: inline-block;
    animation: y2kticker 20s linear infinite;
  `;
  ticker.appendChild(span);
  document.body.appendChild(ticker);

  document.body.style.paddingTop = '22px';

  const styleTag = document.createElement('style');
  styleTag.textContent = `
    @keyframes y2kticker {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }
  `;
  document.head.appendChild(styleTag);

  document.querySelectorAll('.work-item').forEach(item => {
    const onEnter = () => {
      let t = 0;
      const glitchInterval = setInterval(() => {
        t++;
        item.style.filter = `hue-rotate(${Math.random() * 360}deg) saturate(${1.5 + Math.random()})`;
        if (t > 4) {
          clearInterval(glitchInterval);
          item.style.filter = '';
        }
      }, 60);
    };
    item.addEventListener('mouseenter', onEnter);
  });

  window.__aiCleanup = window.__aiCleanup || [];
  window.__aiCleanup.push(() => {
    cancelAnimationFrame(rafId);
    window.removeEventListener('mousemove', onMove);
    trail.forEach(t => t.el.remove());
    ticker.remove();
    styleTag.remove();
    document.body.style.paddingTop = '';
  });
})();
